UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Gel topique ; latex : 20 mg d''aloïne par jour au maximum", "dosage_child": "Usage interne déconseillé chez les moins de 12 ans", "preparation_notes": "Séparer le gel interne transparent du latex jaune périphérique riche en aloïne. Les polysaccharides du gel se dégradent à la chaleur : conserver au réfrigérateur à l''abri de la lumière et de l''air (utiliser le gel frais en quelques jours).", "contraindications": ["Grossesse", "Usage interne chez les enfants de moins de 12 ans", "Maladie rénale"], "traditional_uses": ["Dans la tradition khoïkhoï, la feuille écrasée riche en saponines servait de substitut de savon en moussant dans l''eau", "En médecine populaire d''Afrique australe, application externe contre les plaies, irritations et affections cutanées", "Employée historiquement en médecine traditionnelle d''Afrique australe pour les troubles digestifs, grâce à l''action laxative du latex d''aloès", "Employée traditionnellement par voie locale comme cicatrisant en médecine populaire"], "modern_uses": ["Données extrapolées du genre Aloe (surtout Aloe vera) : gels topiques pour pansements et brûlures légères ; données spécifiques à Aloe maculata limitées", "Étayé par la pharmacologie du latex d''aloès : latex séché titré en aloïne utilisé comme laxatif stimulant à court terme", "Preuves préliminaires / limitées : activité anti-inflammatoire observée surtout in vitro et chez l''animal ; les données cliniques contrôlées sur Aloe maculata font défaut", "Usage pratique établi (non thérapeutique) : feuille riche en saponines utilisée comme tensioactif et nettoyant naturel", "NON étayé par des preuves cliniques humaines adéquates : aucune allégation thérapeutique spécifique à Aloe maculata pour les troubles digestifs internes ou maladies chroniques n''est démontrée cliniquement"]}'::jsonb, true) WHERE id = 'c6f067a4-054c-494f-8036-e948c5c890a2' AND ((translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Gel topique ; latex : 20 mg d''aloïne par jour au maximum' OR (translations->'fr'->>'dosage_child') IS DISTINCT FROM 'Usage interne déconseillé chez les moins de 12 ans' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Séparer le gel interne transparent du latex jaune périphérique riche en aloïne. Les polysaccharides du gel se dégradent à la chaleur : conserver au réfrigérateur à l''abri de la lumière et de l''air (utiliser le gel frais en quelques jours).' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Grossesse", "Usage interne chez les enfants de moins de 12 ans", "Maladie rénale"]'::jsonb OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["Dans la tradition khoïkhoï, la feuille écrasée riche en saponines servait de substitut de savon en moussant dans l''eau", "En médecine populaire d''Afrique australe, application externe contre les plaies, irritations et affections cutanées", "Employée historiquement en médecine traditionnelle d''Afrique australe pour les troubles digestifs, grâce à l''action laxative du latex d''aloès", "Employée traditionnellement par voie locale comme cicatrisant en médecine populaire"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Données extrapolées du genre Aloe (surtout Aloe vera) : gels topiques pour pansements et brûlures légères ; données spécifiques à Aloe maculata limitées", "Étayé par la pharmacologie du latex d''aloès : latex séché titré en aloïne utilisé comme laxatif stimulant à court terme", "Preuves préliminaires / limitées : activité anti-inflammatoire observée surtout in vitro et chez l''animal ; les données cliniques contrôlées sur Aloe maculata font défaut", "Usage pratique établi (non thérapeutique) : feuille riche en saponines utilisée comme tensioactif et nettoyant naturel", "NON étayé par des preuves cliniques humaines adéquates : aucune allégation thérapeutique spécifique à Aloe maculata pour les troubles digestifs internes ou maladies chroniques n''est démontrée cliniquement"]'::jsonb);
UPDATE public.herbs SET dosage_adult = 'Stimulant laxative (adults and adolescents over 12 years): standardized preparation equivalent to 10–30 mg hydroxyanthracene derivatives (calculated as aloin) once daily at night; use lowest effective dose short-term. Contraindicated under 12 years.', traditional_uses = ARRAY['Herbal medicinal product for short-term use in cases of occasional constipation.']::text[] WHERE id = 'd086ca76-314f-4f83-8011-a33d988e180b' AND (dosage_adult IS DISTINCT FROM 'Stimulant laxative (adults and adolescents over 12 years): standardized preparation equivalent to 10–30 mg hydroxyanthracene derivatives (calculated as aloin) once daily at night; use lowest effective dose short-term. Contraindicated under 12 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Herbal medicinal product for short-term use in cases of occasional constipation.']::text[]);
