UPDATE public.herbs SET dosage_adult = 'Infusion or decoction preparation for cutaneous use: 1-2 g of the comminuted herbal substance in 250 ml of water 1-5 times daily. The infusion/decoction (at room temperature) is applied on the afflicted area with a clean dressing. Not recommended under 18 years.', traditional_uses = ARRAY['Traditional herbal medicinal product for the relief of symptoms of mild chronic eczema.']::text[], translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"preparation_notes": "Jus de tige fraîche en usage externe ; faibles doses en formules encadrées ; baies toxiques.", "contraindications": ["Prudence pour un usage interne", "Prudence pendant la grossesse", "Baies toxiques, en particulier chez les enfants"], "modern_uses": ["Anti-inflammatoire topique", "Kératolytique", "Contexte de recherche"]}'::jsonb, true) WHERE id = '3c6c685d-04d2-4d89-8fc7-cb3c3772738e' AND (dosage_adult IS DISTINCT FROM 'Infusion or decoction preparation for cutaneous use: 1-2 g of the comminuted herbal substance in 250 ml of water 1-5 times daily. The infusion/decoction (at room temperature) is applied on the afflicted area with a clean dressing. Not recommended under 18 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product for the relief of symptoms of mild chronic eczema.']::text[] OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Jus de tige fraîche en usage externe ; faibles doses en formules encadrées ; baies toxiques.' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Prudence pour un usage interne", "Prudence pendant la grossesse", "Baies toxiques, en particulier chez les enfants"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Anti-inflammatoire topique", "Kératolytique", "Contexte de recherche"]'::jsonb);
