UPDATE public.herbs SET dosage_adult = 'Standardized extracts equivalent to 40 mg dried rhizome daily, divided into 1–2 single doses (tablets must not be sucked; consult a physician before exceeding 3–6 months of use).', traditional_uses = ARRAY['Herbal medicinal product for the relief of minor neurovegetative menopausal complaints (such as hot flushes and sweating).']::text[], translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Extraits standardisés équivalant à 40 mg de rhizome séché par jour, en 1 ou 2 prises (ne pas sucer les comprimés ; consulter un médecin au-delà de 3 à 6 mois d''utilisation).", "preparation_notes": "Privilégier les extraits standardisés pour un dosage régulier. Les effets peuvent demander 4 à 8 semaines ; limiter la cure à 6 mois en l''absence de données prolongées.", "contraindications": ["Maladie hépatique", "Cancers sensibles aux hormones", "Troubles convulsifs", "Allergie à l''aspirine"], "modern_uses": ["Bouffées de chaleur de la ménopause", "Sueurs nocturnes", "irrégularités menstruelles", "Symptômes du syndrome prémenstruel (SPM)", "Variations d''humeur liées à la ménopause"]}'::jsonb, true) WHERE id = '2b0721df-4488-4963-bf4b-c89015acd16f' AND (dosage_adult IS DISTINCT FROM 'Standardized extracts equivalent to 40 mg dried rhizome daily, divided into 1–2 single doses (tablets must not be sucked; consult a physician before exceeding 3–6 months of use).' OR traditional_uses IS DISTINCT FROM ARRAY['Herbal medicinal product for the relief of minor neurovegetative menopausal complaints (such as hot flushes and sweating).']::text[] OR (translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Extraits standardisés équivalant à 40 mg de rhizome séché par jour, en 1 ou 2 prises (ne pas sucer les comprimés ; consulter un médecin au-delà de 3 à 6 mois d''utilisation).' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Privilégier les extraits standardisés pour un dosage régulier. Les effets peuvent demander 4 à 8 semaines ; limiter la cure à 6 mois en l''absence de données prolongées.' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Maladie hépatique", "Cancers sensibles aux hormones", "Troubles convulsifs", "Allergie à l''aspirine"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Bouffées de chaleur de la ménopause", "Sueurs nocturnes", "irrégularités menstruelles", "Symptômes du syndrome prémenstruel (SPM)", "Variations d''humeur liées à la ménopause"]'::jsonb);
