UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_child": "Non établie", "preparation_notes": "Préparé par fermentation de bulbes entiers sous chaleur et humidité contrôlées (60–90 °C pendant 10–40 jours) sans additifs ; ce vieillissement transforme l''allicine en S-allylcystéine et polyphénols stables tout en réduisant l''odeur. Conserver au frais, à l''abri de l''air et de la lumière.", "contraindications": ["anticoagulants", "chirurgie"], "traditional_uses": ["Dans la tradition alimentaire et médicinale coréenne, l''ail noir fermenté est consommé comme aliment tonique général", "Dans la tradition japonaise, les préparations d''ail sont employées pour la fatigue, la convalescence et la vitalité générale", "Dans les traditions chinoise et coréenne, l''ail est documenté pour les troubles respiratoires et digestifs, les parasitoses et les infections locales", "En médecine populaire méditerranéenne et européenne, les bulbes d''ail étaient employés contre l''hypertension et la mauvaise circulation (l''ail noir fermenté étant une préparation plus récente)"], "modern_uses": ["Données humaines préliminaires : effets antioxydants de l''ail noir et de l''ail vieilli observés dans de petits essais limités", "Preuves préliminaires / limitées : facteurs de risque cardiovasculaire étudiés dans de petits essais d''extrait d''ail vieilli standardisé, sans valeur de recommandation établie", "Preuves préliminaires / limitées : résultats modestes sur des marqueurs immunitaires issus de petits essais d''ail vieilli ; des essais confirmatoires plus vastes manquent", "Applications anticancéreuses : données précliniques in vitro et animales uniquement ; NON étayées par des preuves cliniques humaines adéquates", "Effets antidiabétiques et métaboliques : données principalement chez l''animal ; preuves humaines insuffisantes à ce jour", "Non établi par des preuves cliniques humaines : traitement des infections, de la diarrhée ou de toute pathologie diagnostiquée"]}'::jsonb, true) WHERE id = '7fc16acb-06c8-4431-84f7-112f68455e67' AND ((translations->'fr'->>'dosage_child') IS DISTINCT FROM 'Non établie' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Préparé par fermentation de bulbes entiers sous chaleur et humidité contrôlées (60–90 °C pendant 10–40 jours) sans additifs ; ce vieillissement transforme l''allicine en S-allylcystéine et polyphénols stables tout en réduisant l''odeur. Conserver au frais, à l''abri de l''air et de la lumière.' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["anticoagulants", "chirurgie"]'::jsonb OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["Dans la tradition alimentaire et médicinale coréenne, l''ail noir fermenté est consommé comme aliment tonique général", "Dans la tradition japonaise, les préparations d''ail sont employées pour la fatigue, la convalescence et la vitalité générale", "Dans les traditions chinoise et coréenne, l''ail est documenté pour les troubles respiratoires et digestifs, les parasitoses et les infections locales", "En médecine populaire méditerranéenne et européenne, les bulbes d''ail étaient employés contre l''hypertension et la mauvaise circulation (l''ail noir fermenté étant une préparation plus récente)"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Données humaines préliminaires : effets antioxydants de l''ail noir et de l''ail vieilli observés dans de petits essais limités", "Preuves préliminaires / limitées : facteurs de risque cardiovasculaire étudiés dans de petits essais d''extrait d''ail vieilli standardisé, sans valeur de recommandation établie", "Preuves préliminaires / limitées : résultats modestes sur des marqueurs immunitaires issus de petits essais d''ail vieilli ; des essais confirmatoires plus vastes manquent", "Applications anticancéreuses : données précliniques in vitro et animales uniquement ; NON étayées par des preuves cliniques humaines adéquates", "Effets antidiabétiques et métaboliques : données principalement chez l''animal ; preuves humaines insuffisantes à ce jour", "Non établi par des preuves cliniques humaines : traitement des infections, de la diarrhée ou de toute pathologie diagnostiquée"]'::jsonb);
