UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"preparation_notes": "Faire frémir 1 à 2 g d''écorce interne 15 à 20 minutes ; privilégier les extraits standardisés en alcaloïdes oxindoles pentacycliques (formes sans TOA parfois préférées).", "contraindications": ["Troubles auto-immuns", "Avant une chirurgie", "Greffe d''organe (interaction avec les immunosuppresseurs)", "Leucémie"], "traditional_uses": ["Anti-inflammatoire", "Stimulant immunitaire", "Aide digestive", "Cicatrisation des plaies", "Traitement de l''arthrite"], "modern_uses": ["arthrose", "Arthrite rhumatoïde", "Soutien du système immunitaire", "Inflammation digestive", "Infections virales"]}'::jsonb, true) WHERE id = 'fd02a72d-86b1-4b3c-8348-6586f9390971' AND ((translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Faire frémir 1 à 2 g d''écorce interne 15 à 20 minutes ; privilégier les extraits standardisés en alcaloïdes oxindoles pentacycliques (formes sans TOA parfois préférées).' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Troubles auto-immuns", "Avant une chirurgie", "Greffe d''organe (interaction avec les immunosuppresseurs)", "Leucémie"]'::jsonb OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["Anti-inflammatoire", "Stimulant immunitaire", "Aide digestive", "Cicatrisation des plaies", "Traitement de l''arthrite"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["arthrose", "Arthrite rhumatoïde", "Soutien du système immunitaire", "Inflammation digestive", "Infections virales"]'::jsonb);
