UPDATE public.herbs SET dosage_adult = 'Powdered herbal substance: 0.25-2 g, up to 3 times daily; C) Liquid extract: daily dose: 2-4 ml; D) Tincture: daily dose: 1.5-5 g E) Soft extract: daily dose: 1-2 g. Not recommended under 18 years.', traditional_uses = ARRAY['Traditional herbal medicinal product used in mild dyspeptic/gastrointestinal disorders, and in temporary loss of appetite.']::text[], translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"contraindications": ["Ulcères peptiques", "grossesse"], "modern_uses": ["amer digestif", "hépatoprotecteur", "anti-inflammatoire"]}'::jsonb, true) WHERE id = 'ac1afad1-a75d-4eff-b977-49f4709784d7' AND (dosage_adult IS DISTINCT FROM 'Powdered herbal substance: 0.25-2 g, up to 3 times daily; C) Liquid extract: daily dose: 2-4 ml; D) Tincture: daily dose: 1.5-5 g E) Soft extract: daily dose: 1-2 g. Not recommended under 18 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product used in mild dyspeptic/gastrointestinal disorders, and in temporary loss of appetite.']::text[] OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Ulcères peptiques", "grossesse"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["amer digestif", "hépatoprotecteur", "anti-inflammatoire"]'::jsonb);
