UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"contraindications": ["Contre-indications : Ne pas utiliser si vous avez subi une crise cardiaque/un infarctus du myocarde.", "Effets indésirables connus : Une hypersensibilité, telle qu''une allergie, a été signalée ; dans ce cas, cessez l''utilisation. Certaines personnes peuvent ressentir des troubles gastro-intestinaux légers et/ou des nausées. Cessez l''utilisation et consultez immédiatement un médecin si vous ressentez des étourdissements, de la confusion ou une faiblesse musculaire", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser. Si vous avez une maladie cardiaque, une pression artérielle élevée ou basse, un trouble rénal ou hépatique, du diabète ou de l''œdème (gonflement des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques, ne pas utiliser.", "Contre-indications : Ne pas utiliser si vous avez des problèmes de foie ou de reins."]}'::jsonb, true) WHERE id = '5c4ac506-2e7d-4dfb-a730-0962aea54bcd' AND ((translations->'fr'->'contraindications') IS DISTINCT FROM '["Contre-indications : Ne pas utiliser si vous avez subi une crise cardiaque/un infarctus du myocarde.", "Effets indésirables connus : Une hypersensibilité, telle qu''une allergie, a été signalée ; dans ce cas, cessez l''utilisation. Certaines personnes peuvent ressentir des troubles gastro-intestinaux légers et/ou des nausées. Cessez l''utilisation et consultez immédiatement un médecin si vous ressentez des étourdissements, de la confusion ou une faiblesse musculaire", "Contre-indications : Si vous êtes enceinte ou si vous allaitez, ne pas utiliser. Si vous avez une maladie cardiaque, une pression artérielle élevée ou basse, un trouble rénal ou hépatique, du diabète ou de l''œdème (gonflement des mains, du visage et des pieds) ou si vous prenez des produits contenant des diurétiques, ne pas utiliser.", "Contre-indications : Ne pas utiliser si vous avez des problèmes de foie ou de reins."]'::jsonb);
UPDATE public.herbs SET dosage_adult = 'Oral herbal tea: 1–4 g dried flowers infused 3 times daily between meals; mouth/throat wash: 2–3 g infusion 3–4 times daily; liquid extract: 1–4 ml 3 times daily. Not recommended under 12 years.', traditional_uses = ARRAY['Traditional herbal medicinal product for the symptomatic treatment of mild, spasmodic gastrointestinal complaints including bloating and flatulence.', 'Traditional herbal medicinal product for the symptomatic treatment of minor inflammations in the mouth or the throat.']::text[] WHERE id = '890290c5-b151-494b-8b02-2a7a38808f27' AND (dosage_adult IS DISTINCT FROM 'Oral herbal tea: 1–4 g dried flowers infused 3 times daily between meals; mouth/throat wash: 2–3 g infusion 3–4 times daily; liquid extract: 1–4 ml 3 times daily. Not recommended under 12 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product for the symptomatic treatment of mild, spasmodic gastrointestinal complaints including bloating and flatulence.', 'Traditional herbal medicinal product for the symptomatic treatment of minor inflammations in the mouth or the throat.']::text[]);
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"contraindications": ["Mises en garde et précautions : Éviter les expositions prolongées au soleil, aux rayons UV ou la luminothérapie aux UV. Consulter un fournisseur de soins de santé si vous prenez des médicaments traditionnels. Consulter un praticien de soins de santé si les symptômes persistent ou s''aggravent. La consommation", "Contre-indications : Ne pas utiliser en cas de d''ulcères ou d''inflammation gastro-intestinales et de la maladie du rein et du foie. Ne pas utiliser en cas d''allergie à l''anéthole ou aux plantes appartenant à la famille des Apiacées/Carottes et des Astéracées. Ne pas utiliser si vous êtes enceintes ou", "Effets indésirables connus : Une hypersensibilité (e.g. une allergie) peut se manifester (quelques rares cas ont été rapportés). Si tel est le cas, cesser l''utilisation.", "Mises en garde et précautions : Consulter un praticien de soins de santé si vous êtes enceinte ou si vous allaitez. Consulter un praticien de soins de santé si les symptômes persistent. Consulter un praticien de soins de santé si les symptômes s''aggravent. Consulter un praticien de soins de santé si l''insomn", "Contre-indications : Ne pas utiliser en cas d''allergie à la famille des Astéracées/Composées/Marguerites.", "Effets indésirables connus : Une hypersensibilité (e.g. une allergie) peut se manifester. Si tel est le cas, cesser l''utilisation. Certaines personnes pourraient ressentir de la somnolence. Faire preuve de prudence si vous conduisez de la machinerie lourde ou tout autre véhicule motorisé, ou si vous dev"]}'::jsonb, true) WHERE id = '0da46bba-f165-470b-9cd2-30b150e44b5f' AND ((translations->'fr'->'contraindications') IS DISTINCT FROM '["Mises en garde et précautions : Éviter les expositions prolongées au soleil, aux rayons UV ou la luminothérapie aux UV. Consulter un fournisseur de soins de santé si vous prenez des médicaments traditionnels. Consulter un praticien de soins de santé si les symptômes persistent ou s''aggravent. La consommation", "Contre-indications : Ne pas utiliser en cas de d''ulcères ou d''inflammation gastro-intestinales et de la maladie du rein et du foie. Ne pas utiliser en cas d''allergie à l''anéthole ou aux plantes appartenant à la famille des Apiacées/Carottes et des Astéracées. Ne pas utiliser si vous êtes enceintes ou", "Effets indésirables connus : Une hypersensibilité (e.g. une allergie) peut se manifester (quelques rares cas ont été rapportés). Si tel est le cas, cesser l''utilisation.", "Mises en garde et précautions : Consulter un praticien de soins de santé si vous êtes enceinte ou si vous allaitez. Consulter un praticien de soins de santé si les symptômes persistent. Consulter un praticien de soins de santé si les symptômes s''aggravent. Consulter un praticien de soins de santé si l''insomn", "Contre-indications : Ne pas utiliser en cas d''allergie à la famille des Astéracées/Composées/Marguerites.", "Effets indésirables connus : Une hypersensibilité (e.g. une allergie) peut se manifester. Si tel est le cas, cesser l''utilisation. Certaines personnes pourraient ressentir de la somnolence. Faire preuve de prudence si vous conduisez de la machinerie lourde ou tout autre véhicule motorisé, ou si vous dev"]'::jsonb);
