UPDATE public.herbs SET dosage_adult = 'Herbal tea (infusion or decoction): taken 2–4 times daily; consult a healthcare practitioner if symptoms persist longer than 2 weeks. Not recommended under 18 years.', translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Infusion ou décoction 2 à 4 fois par jour ; consulter un professionnel de santé si les symptômes persistent plus de 2 semaines. Non recommandé chez les moins de 18 ans.", "dosage_child": "Non établie"}'::jsonb, true) WHERE id = '498076ce-a129-498a-9f83-b1d318e0bba5' AND (dosage_adult IS DISTINCT FROM 'Herbal tea (infusion or decoction): taken 2–4 times daily; consult a healthcare practitioner if symptoms persist longer than 2 weeks. Not recommended under 18 years.' OR (translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Infusion ou décoction 2 à 4 fois par jour ; consulter un professionnel de santé si les symptômes persistent plus de 2 semaines. Non recommandé chez les moins de 18 ans.' OR (translations->'fr'->>'dosage_child') IS DISTINCT FROM 'Non établie');
UPDATE public.herbs SET dosage_adult = 'Herbal tea: 2-4 g of the comminuted herbal substance in 250 ml of boiling water as a herbal infusion once daily. Herbal tea: 2-4 g of the comminuted herbal substance in 250 ml of water as a decoction once daily. Not recommended under 12 years.', traditional_uses = ARRAY['Traditional herbal medicinal product for the relief of symptoms related to mild digestive disorders (such as feeling of abdominal fullness, flatulence and slow digestion) and temporary loss of appetite.']::text[] WHERE id = '8dfee339-231c-484f-9880-a7fa88183948' AND (dosage_adult IS DISTINCT FROM 'Herbal tea: 2-4 g of the comminuted herbal substance in 250 ml of boiling water as a herbal infusion once daily. Herbal tea: 2-4 g of the comminuted herbal substance in 250 ml of water as a decoction once daily. Not recommended under 12 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product for the relief of symptoms related to mild digestive disorders (such as feeling of abdominal fullness, flatulence and slow digestion) and temporary loss of appetite.']::text[]);
