UPDATE public.herbs SET dosage_adult = 'Mouthwash: diluted preparations corresponding to 1–5% clove essential oil applied several times daily; traditional clove tea: ~0.5 g crushed buds as infusion. Not recommended under 18 years.', traditional_uses = ARRAY['Traditional herbal medicinal product for the symptomatic treatment of minor inflammations in the mouth or the throat.', 'Traditional herbal medicinal product for the temporary relief of toothache due to a dental cavity.']::text[], translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Bain de bouche : préparations diluées à 1–5 % d''huile essentielle de clou de girofle plusieurs fois par jour ; infusion traditionnelle : ~0,5 g de clous concassés. Non recommandé chez les moins de 18 ans.", "dosage_child": "Quantités culinaires sûres ; huile essentielle de clou de girofle diluée par voie topique dès 2 ans", "preparation_notes": "En cas de mal de dents, appliquer une petite quantité d''huile de girofle sur un coton directement sur la dent. Diluer l''huile pour l''application cutanée. Pour une tisane, laisser frémir 2 à 3 clous de girofle 10 minutes. Éviter les applications répétées d''huile pure sur les gencives.", "contraindications": ["Troubles hémorragiques", "Avant une chirurgie", "Maladie hépatique", "Application pure sur les muqueuses"], "traditional_uses": ["Médicament traditionnel à base de plantes pour le traitement symptomatique des inflammations mineures de la bouche ou de la gorge.", "Médicament traditionnel à base de plantes pour le soulagement temporaire des maux de dents liés à une carie."], "modern_uses": ["Douleur dentaire", "Infections buccales", "Soutien digestif", "Applications antimicrobiennes", "Anti-inflammatoire"]}'::jsonb, true) WHERE id = '63ea55dd-e8a5-4ad7-bd79-d9f4df69341a' AND (dosage_adult IS DISTINCT FROM 'Mouthwash: diluted preparations corresponding to 1–5% clove essential oil applied several times daily; traditional clove tea: ~0.5 g crushed buds as infusion. Not recommended under 18 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product for the symptomatic treatment of minor inflammations in the mouth or the throat.', 'Traditional herbal medicinal product for the temporary relief of toothache due to a dental cavity.']::text[] OR (translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Bain de bouche : préparations diluées à 1–5 % d''huile essentielle de clou de girofle plusieurs fois par jour ; infusion traditionnelle : ~0,5 g de clous concassés. Non recommandé chez les moins de 18 ans.' OR (translations->'fr'->>'dosage_child') IS DISTINCT FROM 'Quantités culinaires sûres ; huile essentielle de clou de girofle diluée par voie topique dès 2 ans' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'En cas de mal de dents, appliquer une petite quantité d''huile de girofle sur un coton directement sur la dent. Diluer l''huile pour l''application cutanée. Pour une tisane, laisser frémir 2 à 3 clous de girofle 10 minutes. Éviter les applications répétées d''huile pure sur les gencives.' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Troubles hémorragiques", "Avant une chirurgie", "Maladie hépatique", "Application pure sur les muqueuses"]'::jsonb OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["Médicament traditionnel à base de plantes pour le traitement symptomatique des inflammations mineures de la bouche ou de la gorge.", "Médicament traditionnel à base de plantes pour le soulagement temporaire des maux de dents liés à une carie."]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Douleur dentaire", "Infections buccales", "Soutien digestif", "Applications antimicrobiennes", "Anti-inflammatoire"]'::jsonb);
