UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Jus de tige fraîche pressé ; 5 à 10 g de décoction de feuilles 2 fois par jour", "dosage_child": "Non établie", "preparation_notes": "Le jus de tige fraîche se prépare juste avant emploi car ses mucilages et composés phénoliques se dégradent vite. Les décoctions de feuilles séchées se consomment dans la journée. Conserver les plantes séchées et extraits à l''abri de la lumière, de l''air et de l''humidité (jusqu''à environ un an pour la plante sèche).", "contraindications": ["grossesse", "hypoglycémie"], "traditional_uses": ["En Afrique de l''Ouest (notamment chez les Igbo et Yoruba), le jus de tige fraîche est bu traditionnellement contre le diabète et la fièvre", "En médecine populaire nigériane et camerounaise, feuilles et tiges sont appliquées sur les plaies, ulcères et maladies cutanées", "En Afrique de l''Ouest, les décoctions sont bues comme expectorant contre la toux, le rhume et les troubles respiratoires", "En médecine populaire régionale, les préparations servaient à faciliter l''accouchement et comme emménagogue", "En Afrique centrale, les infusions de tige et de rhizome sont utilisées contre les rhumatismes et les troubles digestifs"], "modern_uses": ["Preuves préliminaires / limitées : revue systématique étayant des mécanismes hypoglycémiants in vitro et chez l''animal (PMID 32082693)", "Preuves préliminaires / limitées : protection antioxydante démontrée uniquement chez le rat contre des lésions induites par la cyclosporine A (PMID 32175621)", "Preuves préliminaires / limitées : effets anti-inflammatoires, antimicrobiens et cicatrisants décrits dans des études précliniques de laboratoire", "Non étayé par des preuves cliniques humaines : aucun essai clinique randomisé chez l''humain n''a été mené pour le diabète, la toux ou la cicatrisation", "NON étayé par des preuves cliniques humaines : toute allégation présentant Costus afer comme traitement antidiabétique, expectorant ou anti-inflammatoire avéré est infondée"]}'::jsonb, true) WHERE id = 'f52b3aff-8513-443f-ab66-ac72ce631a37' AND ((translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Jus de tige fraîche pressé ; 5 à 10 g de décoction de feuilles 2 fois par jour' OR (translations->'fr'->>'dosage_child') IS DISTINCT FROM 'Non établie' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Le jus de tige fraîche se prépare juste avant emploi car ses mucilages et composés phénoliques se dégradent vite. Les décoctions de feuilles séchées se consomment dans la journée. Conserver les plantes séchées et extraits à l''abri de la lumière, de l''air et de l''humidité (jusqu''à environ un an pour la plante sèche).' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["grossesse", "hypoglycémie"]'::jsonb OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["En Afrique de l''Ouest (notamment chez les Igbo et Yoruba), le jus de tige fraîche est bu traditionnellement contre le diabète et la fièvre", "En médecine populaire nigériane et camerounaise, feuilles et tiges sont appliquées sur les plaies, ulcères et maladies cutanées", "En Afrique de l''Ouest, les décoctions sont bues comme expectorant contre la toux, le rhume et les troubles respiratoires", "En médecine populaire régionale, les préparations servaient à faciliter l''accouchement et comme emménagogue", "En Afrique centrale, les infusions de tige et de rhizome sont utilisées contre les rhumatismes et les troubles digestifs"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Preuves préliminaires / limitées : revue systématique étayant des mécanismes hypoglycémiants in vitro et chez l''animal (PMID 32082693)", "Preuves préliminaires / limitées : protection antioxydante démontrée uniquement chez le rat contre des lésions induites par la cyclosporine A (PMID 32175621)", "Preuves préliminaires / limitées : effets anti-inflammatoires, antimicrobiens et cicatrisants décrits dans des études précliniques de laboratoire", "Non étayé par des preuves cliniques humaines : aucun essai clinique randomisé chez l''humain n''a été mené pour le diabète, la toux ou la cicatrisation", "NON étayé par des preuves cliniques humaines : toute allégation présentant Costus afer comme traitement antidiabétique, expectorant ou anti-inflammatoire avéré est infondée"]'::jsonb);
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "1 à 2 feuilles mâchées par jour ou 3 à 5 g de poudre", "dosage_child": "Non établie", "preparation_notes": "Feuilles fraîches mâchées ou séchées et réduites en poudre ; fréquemment cultivée en jardin.", "contraindications": ["médicaments contre l''hypoglycémie", "grossesse"], "traditional_uses": ["diabète", "Régulation de la glycémie", "affections cutanées"], "modern_uses": ["antidiabétique", "sensibilisant à l''insuline", "anti-inflammatoire"]}'::jsonb, true) WHERE id = '1b25d21d-ab5c-4109-857f-18c23c835aa4' AND ((translations->'fr'->>'dosage_adult') IS DISTINCT FROM '1 à 2 feuilles mâchées par jour ou 3 à 5 g de poudre' OR (translations->'fr'->>'dosage_child') IS DISTINCT FROM 'Non établie' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Feuilles fraîches mâchées ou séchées et réduites en poudre ; fréquemment cultivée en jardin.' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["médicaments contre l''hypoglycémie", "grossesse"]'::jsonb OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["diabète", "Régulation de la glycémie", "affections cutanées"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["antidiabétique", "sensibilisant à l''insuline", "anti-inflammatoire"]'::jsonb);
UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "3 à 6 g de poudre de feuilles ou d''infusion de feuilles séchées par jour", "dosage_child": "Non établie", "preparation_notes": "Les sapogénines stéroïdiennes lipophiles comme la diosgénine étant peu solubles dans l''eau, la tradition utilise des décoctions de rhizome ou de la poudre de feuilles séchées. Conserver les poudres au sec, dans un contenant opaque et hermétique.", "contraindications": ["grossesse", "médicaments contre l''hypoglycémie"], "traditional_uses": ["En médecine ayurvédique, le rhizome (keya/kemuka) est traditionnellement documenté contre le diabète (prameha) et comme purgatif contre la constipation", "En médecine populaire indienne, les préparations de feuilles et de rhizome sont employées contre la fièvre et la toux bronchique", "En ethnobotanique d''Asie du Sud-Est, le rhizome s''applique en pâte sur les articulations rhumatismales et les affections cutanées", "En médecine traditionnelle sri-lankaise et népalaise, les feuilles fraîches étaient mâchées pour aider à abaisser la glycémie"], "modern_uses": ["Étayé par des essais cliniques humains : aucune indication ; la littérature indexée ne recense aucun essai clinique humain adéquat", "Preuves préliminaires / limitées (précliniques uniquement) : effets hypoglycémiants, anti-inflammatoires et antipyrétiques chez l''animal et activité cytotoxique in vitro (PMID 40435094, 27515456)", "Preuves préliminaires / limitées (in vitro) : activité antifongique d''extraits de rhizome en tests de laboratoire", "NON étayé par des preuves cliniques humaines : l''usage de Costus speciosus comme substitut à l''insuline ou traitement antidiabétique/anticancéreux ne repose sur aucune donnée clinique d''efficacité"]}'::jsonb, true) WHERE id = 'ee8e1b17-7e70-418a-91f9-0c0f0a6fc291' AND ((translations->'fr'->>'dosage_adult') IS DISTINCT FROM '3 à 6 g de poudre de feuilles ou d''infusion de feuilles séchées par jour' OR (translations->'fr'->>'dosage_child') IS DISTINCT FROM 'Non établie' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Les sapogénines stéroïdiennes lipophiles comme la diosgénine étant peu solubles dans l''eau, la tradition utilise des décoctions de rhizome ou de la poudre de feuilles séchées. Conserver les poudres au sec, dans un contenant opaque et hermétique.' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["grossesse", "médicaments contre l''hypoglycémie"]'::jsonb OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["En médecine ayurvédique, le rhizome (keya/kemuka) est traditionnellement documenté contre le diabète (prameha) et comme purgatif contre la constipation", "En médecine populaire indienne, les préparations de feuilles et de rhizome sont employées contre la fièvre et la toux bronchique", "En ethnobotanique d''Asie du Sud-Est, le rhizome s''applique en pâte sur les articulations rhumatismales et les affections cutanées", "En médecine traditionnelle sri-lankaise et népalaise, les feuilles fraîches étaient mâchées pour aider à abaisser la glycémie"]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Étayé par des essais cliniques humains : aucune indication ; la littérature indexée ne recense aucun essai clinique humain adéquat", "Preuves préliminaires / limitées (précliniques uniquement) : effets hypoglycémiants, anti-inflammatoires et antipyrétiques chez l''animal et activité cytotoxique in vitro (PMID 40435094, 27515456)", "Preuves préliminaires / limitées (in vitro) : activité antifongique d''extraits de rhizome en tests de laboratoire", "NON étayé par des preuves cliniques humaines : l''usage de Costus speciosus comme substitut à l''insuline ou traitement antidiabétique/anticancéreux ne repose sur aucune donnée clinique d''efficacité"]'::jsonb);
