UPDATE public.herbs SET dosage_adult = 'Herbal tea: 1–6 g daily in 250 ml boiling water before meals; comminuted seeds: 1–2 g 3 times daily before meals (or 0.5 g cold macerate in 150 ml water for 3 hours, 3 times daily); powdered seeds: 380–1,100 mg per dose.', traditional_uses = ARRAY['Traditional herbal medicinal product used for temporary loss of appetite.', 'Traditional herbal medicinal product used for the symptomatic treatment of minor inflammations of the skin.']::text[] WHERE id = 'cfb568ce-838d-4a4f-ae83-ee3e6e1e4fa9' AND (dosage_adult IS DISTINCT FROM 'Herbal tea: 1–6 g daily in 250 ml boiling water before meals; comminuted seeds: 1–2 g 3 times daily before meals (or 0.5 g cold macerate in 150 ml water for 3 hours, 3 times daily); powdered seeds: 380–1,100 mg per dose.' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product used for temporary loss of appetite.', 'Traditional herbal medicinal product used for the symptomatic treatment of minor inflammations of the skin.']::text[]);
UPDATE public.herbs SET dosage_adult = 'Oral herbal tea: 1–6 g daily in divided doses; dry extract (4:1): 295 mg twice daily; soft extract (5–6:1): 500 mg twice daily; cutaneous poultice: 50 g infused in 250 ml water applied warm. Not recommended under 18 years.', traditional_uses = ARRAY['Traditional herbal medicinal product used in temporary loss of appetite.']::text[] WHERE id = '8cb15b5b-04fe-497f-accb-c55e983bef9a' AND (dosage_adult IS DISTINCT FROM 'Oral herbal tea: 1–6 g daily in divided doses; dry extract (4:1): 295 mg twice daily; soft extract (5–6:1): 500 mg twice daily; cutaneous poultice: 50 g infused in 250 ml water applied warm. Not recommended under 18 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product used in temporary loss of appetite.']::text[]);
