UPDATE public.herbs SET dosage_adult = 'powdered herbal substance once daily or 200 mg of powdered herbal substance three times daily Daily dose: 100 mg–600 mg The daily dosage of 100 mg may be gradually increased until obtaining an effect, not exceeding the daily dose of 600 mg. Not recommended under 18 years.', traditional_uses = ARRAY['Traditional herbal medicinal product for the prophylaxis of migraine headaches after serious conditions have been excluded by a medical doctor.']::text[] WHERE id = '7a10a760-d74a-4942-a464-ed352468cbdd' AND (dosage_adult IS DISTINCT FROM 'powdered herbal substance once daily or 200 mg of powdered herbal substance three times daily Daily dose: 100 mg–600 mg The daily dosage of 100 mg may be gradually increased until obtaining an effect, not exceeding the daily dose of 600 mg. Not recommended under 18 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product for the prophylaxis of migraine headaches after serious conditions have been excluded by a medical doctor.']::text[]);
