UPDATE public.herbs SET dosage_adult = 'Whole or bruised flaxseed: 10–15 g 2–3 times daily, or 5–10 g soaked in 250 ml water up to 3 times daily with plenty of fluid (flaxseed oil: 1–2 tablespoons daily). Not recommended under 12 years.', translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Graines de lin entières ou concassées : 10 à 15 g 2 à 3 fois par jour, ou 5 à 10 g macérés dans 250 ml d''eau jusqu''à 3 fois par jour avec beaucoup d''eau (huile de lin : 1 à 2 c. à soupe par jour). Non recommandé chez les moins de 12 ans.", "dosage_child": "Demi-dose adulte", "preparation_notes": "L''acide alpha-linolénique (ALA) s''oxyde très rapidement ; l''huile de lin doit être conservée au réfrigérateur dans un flacon opaque et hermétique et ne doit pas être chauffée. Les graines de lin moulues perdent vite leur stabilité oxydative : il est préférable de les moudre juste avant usage et de les réfrigérer. L''hydratation du mucilage nécessite une macération à froid, et les graines moulues s''intègrent facilement aux aliments.", "contraindications": ["Anticoagulants", "Affections hormonodépendantes (teneur en lignanes)", "Médicaments contre le diabète"]}'::jsonb, true) WHERE id = '53e75b74-5707-4e2f-8c11-6eabd17d3248' AND (dosage_adult IS DISTINCT FROM 'Whole or bruised flaxseed: 10–15 g 2–3 times daily, or 5–10 g soaked in 250 ml water up to 3 times daily with plenty of fluid (flaxseed oil: 1–2 tablespoons daily). Not recommended under 12 years.' OR (translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Graines de lin entières ou concassées : 10 à 15 g 2 à 3 fois par jour, ou 5 à 10 g macérés dans 250 ml d''eau jusqu''à 3 fois par jour avec beaucoup d''eau (huile de lin : 1 à 2 c. à soupe par jour). Non recommandé chez les moins de 12 ans.' OR (translations->'fr'->>'dosage_child') IS DISTINCT FROM 'Demi-dose adulte' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'L''acide alpha-linolénique (ALA) s''oxyde très rapidement ; l''huile de lin doit être conservée au réfrigérateur dans un flacon opaque et hermétique et ne doit pas être chauffée. Les graines de lin moulues perdent vite leur stabilité oxydative : il est préférable de les moudre juste avant usage et de les réfrigérer. L''hydratation du mucilage nécessite une macération à froid, et les graines moulues s''intègrent facilement aux aliments.' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Anticoagulants", "Affections hormonodépendantes (teneur en lignanes)", "Médicaments contre le diabète"]'::jsonb);
UPDATE public.herbs SET dosage_adult = 'Adults and adolescents: 1.5 g crushed fennel fruit in 250 ml boiling water (steep 15 minutes) 3 times daily (4.5 g/day); children 4–12 years: 1.0 g in 100 ml boiling water 3 times daily (3.0 g/day).', traditional_uses = ARRAY['Traditional herbal medicinal product for symptomatic treatment of mild, spasmodic gastrointestinal complaints including bloating and flatulence.', 'Traditional herbal medicinal product used as an expectorant in cough associated with cold.']::text[], translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Adultes et adolescents : 1,5 g de fruits de fenouil dans 250 ml d''eau bouillante (infuser 15 min) 3 fois par jour (4,5 g/jour) ; enfants de 4 à 12 ans : 1,0 g dans 100 ml d''eau bouillante 3 fois par jour (3,0 g/jour).", "traditional_uses": ["Médicament traditionnel à base de plantes pour le traitement symptomatique des troubles gastro-intestinaux légers et spasmodiques (ballonnements, flatulences).", "Médicament traditionnel à base de plantes utilisé comme expectorant dans la toux associée au rhume."]}'::jsonb, true) WHERE id = '0fffede6-4301-4764-a7b1-3ea4828d4ca2' AND (dosage_adult IS DISTINCT FROM 'Adults and adolescents: 1.5 g crushed fennel fruit in 250 ml boiling water (steep 15 minutes) 3 times daily (4.5 g/day); children 4–12 years: 1.0 g in 100 ml boiling water 3 times daily (3.0 g/day).' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product for symptomatic treatment of mild, spasmodic gastrointestinal complaints including bloating and flatulence.', 'Traditional herbal medicinal product used as an expectorant in cough associated with cold.']::text[] OR (translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Adultes et adolescents : 1,5 g de fruits de fenouil dans 250 ml d''eau bouillante (infuser 15 min) 3 fois par jour (4,5 g/jour) ; enfants de 4 à 12 ans : 1,0 g dans 100 ml d''eau bouillante 3 fois par jour (3,0 g/jour).' OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["Médicament traditionnel à base de plantes pour le traitement symptomatique des troubles gastro-intestinaux légers et spasmodiques (ballonnements, flatulences).", "Médicament traditionnel à base de plantes utilisé comme expectorant dans la toux associée au rhume."]'::jsonb);
