UPDATE public.herbs SET dosage_adult = 'Herbal tea or standardized preparation equivalent to 20–30 mg hydroxyanthracene derivatives (calculated as glucofrangulin A) once daily at night; limit short-term use to 1–2 weeks. Contraindicated under 12 years.', traditional_uses = ARRAY['Herbal medicinal product for short-term use in cases of occasional constipation.']::text[], translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Infusion ou préparation standardisée équivalant à 20–30 mg de dérivés hydroxyanthracéniques (calculés en glucofranguline A) une fois le soir ; usage bref (1 à 2 semaines max). Contre-indiqué chez les moins de 12 ans.", "dosage_child": "Ne pas administrer aux enfants de moins de 12 ans", "preparation_notes": "Utiliser uniquement de l''écorce vieillie (l''écorce fraîche provoque des vomissements).", "contraindications": ["Grossesse contre-indiquée", "Enfants de moins de 12 ans", "Obstruction intestinale"], "traditional_uses": ["Médicament à base de plantes pour un usage à court terme en cas de constipation occasionnelle."], "modern_uses": ["Usage laxatif", "Régularité intestinale"]}'::jsonb, true) WHERE id = 'c730c03b-279c-4aa5-88ba-ee29ffb9d282' AND (dosage_adult IS DISTINCT FROM 'Herbal tea or standardized preparation equivalent to 20–30 mg hydroxyanthracene derivatives (calculated as glucofrangulin A) once daily at night; limit short-term use to 1–2 weeks. Contraindicated under 12 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Herbal medicinal product for short-term use in cases of occasional constipation.']::text[] OR (translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Infusion ou préparation standardisée équivalant à 20–30 mg de dérivés hydroxyanthracéniques (calculés en glucofranguline A) une fois le soir ; usage bref (1 à 2 semaines max). Contre-indiqué chez les moins de 12 ans.' OR (translations->'fr'->>'dosage_child') IS DISTINCT FROM 'Ne pas administrer aux enfants de moins de 12 ans' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Utiliser uniquement de l''écorce vieillie (l''écorce fraîche provoque des vomissements).' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Grossesse contre-indiquée", "Enfants de moins de 12 ans", "Obstruction intestinale"]'::jsonb OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["Médicament à base de plantes pour un usage à court terme en cas de constipation occasionnelle."]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Usage laxatif", "Régularité intestinale"]'::jsonb);
