UPDATE public.herbs SET dosage_adult = 'Motion sickness: 1–2 g dried rhizome 1 hour before travel (or 750 mg 30 minutes before travel); typical adult extract/powder range: 250–1,000 mg 2–4 times daily. Not recommended under 18 years.', traditional_uses = ARRAY[' Herbal medicinal product for the prevention of nausea and vomiting in motion sickness.', 'Traditional herbal medicinal product for the symptomatic relief of travel sickness.', 'Traditional herbal medicinal product for symptomatic treatment of mild, spasmodic gastrointestinal complaints including bloating and flatulence.']::text[], translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"traditional_uses": ["Soulagement de la nausée et des vomissements", "Stimulant digestif", "Remède contre le rhume et la grippe", "Améliorant de la circulation", "Agent anti-inflammatoire"]}'::jsonb, true) WHERE id = 'af42fb3c-6d3b-4ea5-a827-7e23861433c8' AND (dosage_adult IS DISTINCT FROM 'Motion sickness: 1–2 g dried rhizome 1 hour before travel (or 750 mg 30 minutes before travel); typical adult extract/powder range: 250–1,000 mg 2–4 times daily. Not recommended under 18 years.' OR traditional_uses IS DISTINCT FROM ARRAY[' Herbal medicinal product for the prevention of nausea and vomiting in motion sickness.', 'Traditional herbal medicinal product for the symptomatic relief of travel sickness.', 'Traditional herbal medicinal product for symptomatic treatment of mild, spasmodic gastrointestinal complaints including bloating and flatulence.']::text[] OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["Soulagement de la nausée et des vomissements", "Stimulant digestif", "Remède contre le rhume et la grippe", "Améliorant de la circulation", "Agent anti-inflammatoire"]'::jsonb);
