UPDATE public.herbs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "3 à 6 g de feuilles séchées", "preparation_notes": "Infuser ou décocter les feuilles séchées dans l''eau chaude (ou appliquer les feuilles fraîches réchauffées en cataplasme cutané). Conserver les feuilles séchées dans un contenant hermétique à l''abri de la lumière et de l''humidité pendant 1 à 2 ans.", "contraindications": ["Prudence pendant la grossesse", "Problèmes rénaux"], "traditional_uses": ["En médecine traditionnelle polynésienne, l''infusion de feuilles était utilisée de génération en génération contre la fièvre.", "En ethnobotanique océanienne, les feuilles écrasées ou tiédies s''appliquaient en externe contre les douleurs articulaires et musculaires.", "Dans la tradition des îles du Pacifique, les cataplasmes de feuilles traitaient les affections cutanées et plaies superficielles.", "Dans les traditions culinaires du Pacifique, la feuille servait surtout d''emballage alimentaire pour la cuisson plutôt que de plante médicinale.", "Dans plusieurs cultures du Pacifique, les préparations de feuilles étaient prises par voie interne contre la fièvre et les malaises généraux."], "modern_uses": ["Preuves préliminaires / limitées : des lignines alcalines de feuilles de Morinda citrifolia ont montré une activité immunomodulatrice in vitro (PMID 38055562 ; résultats de laboratoire, hors essais cliniques humains).", "Preuves préliminaires / limitées : l''extrait de feuille de noni a favorisé in vitro la différenciation ostéogénique de cellules parodontales humaines (PMID 24682022), sans essai clinique humain à ce jour.", "Données précliniques uniquement : une activité anti-inflammatoire, analgésique et antimicrobienne des feuilles a été observée en modèle de laboratoire.", "Données précliniques uniquement : une activité cicatrisante des extraits de feuilles a été décrite chez l''animal ou in vitro.", "NON étayé par des preuves cliniques humaines : l''efficacité des feuilles de noni contre les douleurs articulaires, la fièvre ou les affections cutanées n''est pas établie par des essais cliniques contrôlés"]}'::jsonb, true) WHERE id = 'e26906c9-39e3-41d7-ba15-53ee038fabb5' AND ((translations->'fr'->>'dosage_adult') IS DISTINCT FROM '3 à 6 g de feuilles séchées' OR (translations->'fr'->>'preparation_notes') IS DISTINCT FROM 'Infuser ou décocter les feuilles séchées dans l''eau chaude (ou appliquer les feuilles fraîches réchauffées en cataplasme cutané). Conserver les feuilles séchées dans un contenant hermétique à l''abri de la lumière et de l''humidité pendant 1 à 2 ans.' OR (translations->'fr'->'contraindications') IS DISTINCT FROM '["Prudence pendant la grossesse", "Problèmes rénaux"]'::jsonb OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["En médecine traditionnelle polynésienne, l''infusion de feuilles était utilisée de génération en génération contre la fièvre.", "En ethnobotanique océanienne, les feuilles écrasées ou tiédies s''appliquaient en externe contre les douleurs articulaires et musculaires.", "Dans la tradition des îles du Pacifique, les cataplasmes de feuilles traitaient les affections cutanées et plaies superficielles.", "Dans les traditions culinaires du Pacifique, la feuille servait surtout d''emballage alimentaire pour la cuisson plutôt que de plante médicinale.", "Dans plusieurs cultures du Pacifique, les préparations de feuilles étaient prises par voie interne contre la fièvre et les malaises généraux."]'::jsonb OR (translations->'fr'->'modern_uses') IS DISTINCT FROM '["Preuves préliminaires / limitées : des lignines alcalines de feuilles de Morinda citrifolia ont montré une activité immunomodulatrice in vitro (PMID 38055562 ; résultats de laboratoire, hors essais cliniques humains).", "Preuves préliminaires / limitées : l''extrait de feuille de noni a favorisé in vitro la différenciation ostéogénique de cellules parodontales humaines (PMID 24682022), sans essai clinique humain à ce jour.", "Données précliniques uniquement : une activité anti-inflammatoire, analgésique et antimicrobienne des feuilles a été observée en modèle de laboratoire.", "Données précliniques uniquement : une activité cicatrisante des extraits de feuilles a été décrite chez l''animal ou in vitro.", "NON étayé par des preuves cliniques humaines : l''efficacité des feuilles de noni contre les douleurs articulaires, la fièvre ou les affections cutanées n''est pas établie par des essais cliniques contrôlés"]'::jsonb);
