UPDATE public.herbs SET dosage_adult = 'Powdered feverfew herb: 100 mg once daily up to 200 mg 3 times daily (100–600 mg/day; start at 100 mg and titrate gradually). Not recommended under 18 years.', traditional_uses = ARRAY['Traditional herbal medicinal product for the prophylaxis of migraine headaches after serious conditions have been excluded by a medical doctor.']::text[], translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Poudre de plante : 100 mg une fois par jour jusqu''à 200 mg 3 fois par jour (100 à 600 mg/jour ; augmenter progressivement depuis 100 mg). Non recommandé chez les moins de 18 ans.", "traditional_uses": ["Médicament traditionnel à base de plantes pour la prophylaxie des crises de migraine (après exclusion d''une affection grave par un médecin)."]}'::jsonb, true) WHERE id = '7c217275-5cfc-4010-a34b-85723aef63af' AND (dosage_adult IS DISTINCT FROM 'Powdered feverfew herb: 100 mg once daily up to 200 mg 3 times daily (100–600 mg/day; start at 100 mg and titrate gradually). Not recommended under 18 years.' OR traditional_uses IS DISTINCT FROM ARRAY['Traditional herbal medicinal product for the prophylaxis of migraine headaches after serious conditions have been excluded by a medical doctor.']::text[] OR (translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Poudre de plante : 100 mg une fois par jour jusqu''à 200 mg 3 fois par jour (100 à 600 mg/jour ; augmenter progressivement depuis 100 mg). Non recommandé chez les moins de 18 ans.' OR (translations->'fr'->'traditional_uses') IS DISTINCT FROM '["Médicament traditionnel à base de plantes pour la prophylaxie des crises de migraine (après exclusion d''une affection grave par un médecin)."]'::jsonb);
UPDATE public.herbs SET dosage_adult = 'Cutaneous use only: liquid or semi-solid preparations containing 0.5–10% tea tree essential oil applied to affected skin 1–3 times daily (or 0.7–1 ml essential oil stirred into 100 ml water as wash/rinse). Never ingest.', translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr}', COALESCE(translations->'fr', '{}'::jsonb) || '{"dosage_adult": "Usage cutané uniquement : solutions ou préparations à 0,5–10 % d''huile essentielle d''arbre à thé appliquées 1 à 3 fois par jour (ou 0,7–1 ml dans 100 ml d''eau en lotion). Ne pas ingérer."}'::jsonb, true) WHERE id = '672ee6ad-ffe1-418b-afe1-08aa46008967' AND (dosage_adult IS DISTINCT FROM 'Cutaneous use only: liquid or semi-solid preparations containing 0.5–10% tea tree essential oil applied to affected skin 1–3 times daily (or 0.7–1 ml essential oil stirred into 100 ml water as wash/rinse). Never ingest.' OR (translations->'fr'->>'dosage_adult') IS DISTINCT FROM 'Usage cutané uniquement : solutions ou préparations à 0,5–10 % d''huile essentielle d''arbre à thé appliquées 1 à 3 fois par jour (ou 0,7–1 ml dans 100 ml d''eau en lotion). Ne pas ingérer.');
