UPDATE public.herb_faqs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,answer}', to_jsonb('Réactions indésirables connues : De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l''extrait de thé vert ont été signalés (au Canada et à l''international). Contre-indications : Cessez l''utilisation et consultez un praticien de soins de santé si des symptômes de troubles digestifs (p. ex. diarrhée) surviennent, s''aggravent ou persistent au-delà de 3 jours. Ne pas utiliser ce produit si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme). . Réactions indésirables connues : Peut causer un léger inconfort gastro-intestinal (comme des gaz, des ballonnements, des crampes). Cessez l''utilisation si une hypersensibilité/allergie survient. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche.'::text), true) WHERE id = '852817bb-b269-4186-8502-ecafb496bbe4' AND ((translations->'fr'->>'answer') IS DISTINCT FROM 'Réactions indésirables connues : De rares cas imprévisibles de lésions hépatiques associés à des produits contenant de l''extrait de thé vert ont été signalés (au Canada et à l''international). Contre-indications : Cessez l''utilisation et consultez un praticien de soins de santé si des symptômes de troubles digestifs (p. ex. diarrhée) surviennent, s''aggravent ou persistent au-delà de 3 jours. Ne pas utiliser ce produit si vous avez un état immunodéprimé (p. ex. SIDA, lymphome, patients sous traitement corticostéroïdien à long terme). . Réactions indésirables connues : Peut causer un léger inconfort gastro-intestinal (comme des gaz, des ballonnements, des crampes). Cessez l''utilisation si une hypersensibilité/allergie survient. Ces mises en garde proviennent des étiquettes et des monographies rattachées à cette fiche.');
