UPDATE public.herb_faqs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,answer}', to_jsonb('Dans la tradition khoïkhoï, la feuille écrasée riche en saponines servait de substitut de savon en moussant dans l''eau. En médecine populaire d''Afrique australe, application externe contre les plaies, irritations et affections cutanées. Employée historiquement en médecine traditionnelle d''Afrique australe pour les troubles digestifs, grâce à l''action laxative du latex d''aloès. (Relevé dans les monographies et les produits homologués : Commission E ; PubMed ; WHO Vol.1 (1999) ; WHO Vol.3 (2007).)'::text), true) WHERE id = '4aac4b9f-17e1-4d9e-b248-ea296648d046' AND ((translations->'fr'->>'answer') IS DISTINCT FROM 'Dans la tradition khoïkhoï, la feuille écrasée riche en saponines servait de substitut de savon en moussant dans l''eau. En médecine populaire d''Afrique australe, application externe contre les plaies, irritations et affections cutanées. Employée historiquement en médecine traditionnelle d''Afrique australe pour les troubles digestifs, grâce à l''action laxative du latex d''aloès. (Relevé dans les monographies et les produits homologués : Commission E ; PubMed ; WHO Vol.1 (1999) ; WHO Vol.3 (2007).)');
