UPDATE public.herb_faqs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,answer}', to_jsonb('En médecine ayurvédique, le rhizome (keya/kemuka) est traditionnellement documenté contre le diabète (prameha) et comme purgatif contre la constipation. En médecine populaire indienne, les préparations de feuilles et de rhizome sont employées contre la fièvre et la toux bronchique. En ethnobotanique d''Asie du Sud-Est, le rhizome s''applique en pâte sur les articulations rhumatismales et les affections cutanées. (Relevé dans les monographies et les produits homologués : Kew POWO (Plants of the World Online) ; NCBI Taxonomy ; PubMed ; WHO Vol.2 (2000).)'::text), true) WHERE id = '1c90aac9-45b6-4a8f-abbb-f82d9728f07b' AND ((translations->'fr'->>'answer') IS DISTINCT FROM 'En médecine ayurvédique, le rhizome (keya/kemuka) est traditionnellement documenté contre le diabète (prameha) et comme purgatif contre la constipation. En médecine populaire indienne, les préparations de feuilles et de rhizome sont employées contre la fièvre et la toux bronchique. En ethnobotanique d''Asie du Sud-Est, le rhizome s''applique en pâte sur les articulations rhumatismales et les affections cutanées. (Relevé dans les monographies et les produits homologués : Kew POWO (Plants of the World Online) ; NCBI Taxonomy ; PubMed ; WHO Vol.2 (2000).)');
