UPDATE public.herb_faqs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,answer}', to_jsonb('En médecine traditionnelle polynésienne, l''infusion de feuilles était utilisée de génération en génération contre la fièvre. En ethnobotanique océanienne, les feuilles écrasées ou tiédies s''appliquaient en externe contre les douleurs articulaires et musculaires. Dans la tradition des îles du Pacifique, les cataplasmes de feuilles traitaient les affections cutanées et plaies superficielles. (Relevé dans les monographies et les produits homologués : PubMed ; WHO Vol.3 (2007) ; WHO Vol.4 (2009).)'::text), true) WHERE id = 'd6cd79a9-f2d4-458a-88e1-57be7b172c8e' AND ((translations->'fr'->>'answer') IS DISTINCT FROM 'En médecine traditionnelle polynésienne, l''infusion de feuilles était utilisée de génération en génération contre la fièvre. En ethnobotanique océanienne, les feuilles écrasées ou tiédies s''appliquaient en externe contre les douleurs articulaires et musculaires. Dans la tradition des îles du Pacifique, les cataplasmes de feuilles traitaient les affections cutanées et plaies superficielles. (Relevé dans les monographies et les produits homologués : PubMed ; WHO Vol.3 (2007) ; WHO Vol.4 (2009).)');
