UPDATE public.herb_faqs SET translations = jsonb_set(COALESCE(translations, '{}'::jsonb), '{fr,answer}', to_jsonb('2-4 g de racine séchée en infusion 3 fois par jour ; 2-4 ml de teinture 3 fois par jour. Il s''agit de la posologie figurant sur l''étiquette ou la monographie, et non d''une recommandation personnelle. (Health Canada LNHPD ; PubMed.)'::text), true) WHERE id = 'f56bb9a3-4790-4235-ae88-7011cb5085c2' AND ((translations->'fr'->>'answer') IS DISTINCT FROM '2-4 g de racine séchée en infusion 3 fois par jour ; 2-4 ml de teinture 3 fois par jour. Il s''agit de la posologie figurant sur l''étiquette ou la monographie, et non d''une recommandation personnelle. (Health Canada LNHPD ; PubMed.)');
UPDATE public.herb_faqs SET answer = 'Dry extract: 240 mg 2–3 times daily (480–720 mg/day); liquid extract: 1 g 2–4 times daily (2–4 g/day); tincture: 1 ml 1–3 times daily (1–3 ml/day). Not recommended under 18 years. This is the labelled or monograph dose recorded for this entry, not a personal recommendation. (Commission E; EMA; European Medicines Agency (HMPC); WHO Vol.1 (1999).)' WHERE id = '0173e43a-4397-4aee-8bfb-f0f79b047e48' AND (answer IS DISTINCT FROM 'Dry extract: 240 mg 2–3 times daily (480–720 mg/day); liquid extract: 1 g 2–4 times daily (2–4 g/day); tincture: 1 ml 1–3 times daily (1–3 ml/day). Not recommended under 18 years. This is the labelled or monograph dose recorded for this entry, not a personal recommendation. (Commission E; EMA; European Medicines Agency (HMPC); WHO Vol.1 (1999).)');
UPDATE public.herb_faqs SET answer = 'Traditional herbal medicinal product for temporary loss of appetite. Traditional herbal medicinal product for mild dyspeptic/gastrointestinal disorders. (Recorded from licensed-product and monograph sources: Commission E; EMA; European Medicines Agency (HMPC); WHO Vol.1 (1999).)' WHERE id = '1cc304be-27f1-4456-8b2a-286136de2aed' AND (answer IS DISTINCT FROM 'Traditional herbal medicinal product for temporary loss of appetite. Traditional herbal medicinal product for mild dyspeptic/gastrointestinal disorders. (Recorded from licensed-product and monograph sources: Commission E; EMA; European Medicines Agency (HMPC); WHO Vol.1 (1999).)');
UPDATE public.herb_faqs SET answer = 'Herbal tea: 2-4 g corresponding to 3 times 1 g herbal substance per day. Indication b) Daily dose: Comminuted herbal substance as herbal tea: 2.5-5 g corresponding to 1 to 2 times 2.5 g herbal substance per day. For tea preparation, pour 150 ml of boiling water over the herbal substance. Steep for 15 minutes stirring frequently. Not recommended under 18 years. This is the labelled or monograph dose recorded for this entry, not a personal recommendation. (European Medicines Agency (HMPC); Health Canada LNHPD; PubMed.)' WHERE id = 'b3e3a1d2-8a04-4fb8-b3ce-31fb8f647286' AND (answer IS DISTINCT FROM 'Herbal tea: 2-4 g corresponding to 3 times 1 g herbal substance per day. Indication b) Daily dose: Comminuted herbal substance as herbal tea: 2.5-5 g corresponding to 1 to 2 times 2.5 g herbal substance per day. For tea preparation, pour 150 ml of boiling water over the herbal substance. Steep for 15 minutes stirring frequently. Not recommended under 18 years. This is the labelled or monograph dose recorded for this entry, not a personal recommendation. (European Medicines Agency (HMPC); Health Canada LNHPD; PubMed.)');
UPDATE public.herb_faqs SET answer = 'Decoction: 10 g fresh leaves or 5 g dried leaves in 150 ml water simmered to 100 ml twice daily; dried leaf infusion: 6–10 g up to 3 times daily (6–30 g/day). This is the labelled or monograph dose recorded for this entry, not a personal recommendation. (European Medicines Agency (HMPC); GBIF; ITIS; NCBI Taxonomy; PubMed.)' WHERE id = '6e4c8aba-2420-406d-8b5d-4e5f016a81ae' AND (answer IS DISTINCT FROM 'Decoction: 10 g fresh leaves or 5 g dried leaves in 150 ml water simmered to 100 ml twice daily; dried leaf infusion: 6–10 g up to 3 times daily (6–30 g/day). This is the labelled or monograph dose recorded for this entry, not a personal recommendation. (European Medicines Agency (HMPC); GBIF; ITIS; NCBI Taxonomy; PubMed.)');
